    munch WF m0 m1 -> wmono asegs m0 m1 -> mem_inv asegs m1 ->
    (forall m2 a0v (y1 y5 y6 y7 y8 y9 y11 y12 y13 y14 y15 y16 y17 y18 y19 y20 y21 y22 y28 : word),
       munch WF m0 m2 -> wmono asegs m0 m2 -> mem_inv asegs m2 ->
       rresA HW RK NSP TLP (RF_huf_rs_pure.rs_tail ws (zlen ws) iS) m2 a0v ->
       evtF asegs RNG Q (EXIT m2 a0v y1 y5 y6 y7 y8 y9 y11 y12 y13 y14 y15 y16 y17 y18 y19 y20 y21 y22 y28)) ->
    evtF asegs RNG Q
      (MS (mkR x1 sp gp tp (Z_to_bv 64 12) (Z_to_bv 64 (zlen ws + 1)) x7 (Z_to_bv 64 RK) (Z_to_bv 64 (zlen ws)) (Z_to_bv 64 (-20))
               (Z_to_bv 64 NSP) (Z_to_bv 64 TLP) x13 x14 x15 (Z_to_bv 64 wt) (Z_to_bv 64 1) (Z_to_bv 64 iS) (Z_to_bv 64 HW)
               (Z_to_bv 64 2147450880) (Z_to_bv 64 TLP) (Z_to_bv 64 NSP) x23 x24 x25 x26 x27 x28 x29 x30 x31)
          F (Z_to_bv 64 0x95380) fc None m1 (seg_rom asegs)).
